<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue'
import {actor,api,error,reportError,type Case} from './api'
type Memory={id:string;merchant_id:string;product_id:string;source_case_id:string;source_id:string;quote:string;expires_on:string;as_of:string;status:string;effective_status:string;revision:number;note:string;verifier_id:string|null}
const rows=ref<Memory[]>([]),busy=ref(false),note=ref(''),selected=ref<Memory|null>(null),offset=ref(0)
const correcting=ref(false),originCases=ref<Case[]>([]),sourceCase=ref(''),sourceId=ref(''),productId=ref(''),quote=ref(''),expiry=ref('')
const eligibleCases=()=>originCases.value.filter(item=>['approved','confirmed'].includes(item.status))
async function edit(row:Memory){const current=++editEpoch;originCases.value=[];sourceLoading.value=true;selected.value=row;note.value='';correcting.value=false;sourceCase.value=row.source_case_id;sourceId.value=row.source_id;productId.value=row.product_id;quote.value=row.quote;expiry.value=row.expires_on;try{const items=await api<Case[]>(`/cases?limit=100&merchant_id=${encodeURIComponent(row.merchant_id)}`);if(current===editEpoch&&selected.value?.id===row.id)originCases.value=items}catch(cause){if(current===editEpoch)reportError(cause,'批准来源读取失败')}finally{if(current===editEpoch)sourceLoading.value=false}}
async function correct(){if(!selected.value||sourceLoading.value)return;busy.value=true;error.value='';try{await api(`/memories/${selected.value.id}`,{method:'PUT',body:JSON.stringify({expected_revision:selected.value.revision,source_case_id:sourceCase.value,source_id:sourceId.value,product_id:productId.value,quote:quote.value,expires_on:expiry.value,note:note.value})});selected.value=null;correcting.value=false;await load()}catch(cause){reportError(cause,'纠正来源失败')}finally{busy.value=false}}
let editEpoch=0
const sourceLoading=ref(false)
onUnmounted(()=>{editEpoch++})
const labels:Record<string,string>={candidate:'待核验',verified:'已核验',expired:'已过期',source_changed:'来源已变化',deleted:'已删除'}
async function load(){busy.value=true;try{rows.value=await api<Memory[]>(`/memories?limit=50&offset=${offset.value}`)}catch(cause){reportError(cause,'记忆读取失败')}finally{busy.value=false}}
onMounted(load)
async function action(kind:'confirm'|'delete'){
  if(!selected.value)return
  busy.value=true;error.value=''
  try{await api(`/memories/${selected.value.id}/${kind}`,{method:'POST',body:JSON.stringify({expected_revision:selected.value.revision,note:note.value})});selected.value=null;note.value='';await load()}
  catch(cause){reportError(cause,'记忆操作失败')}finally{busy.value=false}
}
async function page(delta:number){offset.value=Math.max(0,offset.value+delta);await load()}
</script>
<template><main class="page"><section class="page-heading"><div><p class="eyebrow">VERIFIED REFERENCE</p><h1>记忆与核验</h1><p class="muted">只复用有来源、经人工确认的历史摘录。来源变化或过期时停止复用。</p></div><button class="secondary" :disabled="busy" @click="load">刷新记忆</button></section><div class="notice"><p>候选从已批准案件的证据区创建。纠正来源或摘录后需要重新核验；删除会清空活跃摘录，原案件和历史运行仍保留。</p></div><p v-if="!rows.length" class="empty">本页暂无可见记忆。</p><article v-for="row in rows" :key="row.id" class="panel"><div class="panel-heading"><h2>{{row.product_id}}</h2><span class="badge">{{labels[row.effective_status]||row.effective_status}} · v{{row.revision}}</span></div><p class="memory-quote">{{row.quote||'摘录已清空'}}</p><p class="muted">{{row.merchant_id}} · 适用日期{{row.as_of}} · 有效至{{row.expires_on}} · {{row.verifier_id||'尚未核验'}}</p><p>{{row.note}}</p><router-link :to="`/cases/${row.source_case_id}`">核对原案件与来源 {{row.source_id}} →</router-link><div v-if="actor?.role!=='admin' && row.status!=='deleted'" class="action-bar"><button class="secondary" :disabled="busy" @click="edit(row)">管理此记忆版本</button></div><form v-if="selected?.id===row.id" class="search-form" @submit.prevent="correcting?correct():action('confirm')"><label>核验／纠正／删除说明<textarea v-model="note" required maxlength="500" rows="3"></textarea></label><template v-if="correcting"><p v-if="sourceLoading" role="status" class="muted">正在核对该商家的批准来源…</p><label>新的已批准案件<select v-model="sourceCase" required><option v-for="item in eligibleCases()" :key="item.id" :value="item.id">{{item.title}} · {{item.id}}</option></select></label><label>适用商品编号<input v-model="productId" required maxlength="80"></label><label>新批准来源编号<input v-model="sourceId" required maxlength="100"></label><label>新原文摘录<textarea v-model="quote" required minlength="10" maxlength="500" rows="3"></textarea></label><label>新有效期<input v-model="expiry" type="date" required></label><p class="muted">从新案件证据区复制来源编号与原文；服务器再次检查同商家、SKU与批准来源。纠正后退回待核验。</p><button type="button" class="primary" :disabled="busy||sourceLoading||!note.trim()" @click="correct">保存纠正并重新核验</button></template><div class="action-bar"><button v-if="actor?.role==='reviewer' && row.status==='candidate' && !correcting" class="primary" :disabled="busy||!note.trim()">核验此候选</button><button v-if="actor?.role==='reviewer'" type="button" class="secondary" :disabled="busy" @click="correcting=!correcting">{{correcting?'收起纠正':'纠正来源与摘录'}}</button><button type="button" class="secondary" :disabled="busy||!note.trim()" @click="action('delete')">删除此记忆</button><button type="button" class="text-button" :disabled="busy" @click="selected=null">取消</button></div></form></article><div class="action-bar"><button class="secondary" :disabled="busy||offset===0" @click="page(-50)">上一页</button><span class="muted">第{{Math.floor(offset/50)+1}}页</span><button class="secondary" :disabled="busy||rows.length<50" @click="page(50)">下一页</button></div></main></template>
